begin;

create temporary table coding_question_seed (
  collection_slug text not null,
  slug text not null,
  title text not null,
  problem_statement text not null,
  difficulty text not null,
  topic_tags text[] not null,
  constraints jsonb not null,
  examples jsonb not null,
  starter_code_by_language jsonb not null,
  points integer not null
) on commit drop;

insert into coding_question_seed
select 'cpp-programming', seed.slug, seed.title, seed.problem_statement, seed.difficulty,
       seed.topic_tags, seed.constraints, seed.examples,
       seed.starter_code_by_language, seed.points
from jsonb_to_recordset($seed$[{"slug":"top-k-frequent-values-cpp","title":"Return the K Most Frequent Values","problem_statement":"Return k values ordered by descending occurrence count; ties are ordered by ascending numeric value. Do not return duplicate values.","difficulty":"Medium","topic_tags":["C++","Unordered Map","Heap"],"constraints":["0 <= values.size() <= 100000","0 <= k <= number of distinct values"],"examples":[{"input":"[4,4,1,1,1,2], k=2","output":"[1,4]"},{"input":"[7,8,8,7], k=2","output":"[7,8]"}],"signature":"std::vector<int> topKFrequent(const std::vector<int>& values, std::size_t k)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> topKFrequent(const std::vector<int>& values, std::size_t k) {\n    // Return the K Most Frequent Values: implement the specified behavior.\n    return {};\n}"}},{"slug":"sliding-window-maximum-cpp","title":"Maximum of Every Sliding Window","problem_statement":"For each contiguous window of width, return its maximum while preserving window order. Use an approach that runs in linear time.","difficulty":"Medium","topic_tags":["C++","Deque","Sliding Window"],"constraints":["1 <= width <= values.size()","values.size() <= 100000"],"examples":[{"input":"[1,3,-1,-3,5,3,6,7], width=3","output":"[3,3,5,5,6,7]"},{"input":"[4,2,9], width=2","output":"[4,9]"}],"signature":"std::vector<int> slidingWindowMaximum(const std::vector<int>& values, std::size_t width)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> slidingWindowMaximum(const std::vector<int>& values, std::size_t width) {\n    // Maximum of Every Sliding Window: implement the specified behavior.\n    return {};\n}"}},{"slug":"minimum-covering-window-cpp","title":"Find the Minimum Covering Window","problem_statement":"Return the shortest substring containing every byte in required with its multiplicity. Choose the earliest window on ties; return an empty string if no such substring exists.","difficulty":"Hard","topic_tags":["C++","String","Sliding Window","Hash Map"],"constraints":["text.size() and required.size() are at most 100000","Inputs are byte strings"],"examples":[{"input":"\"ADOBECODEBANC\", \"ABC\"","output":"\"BANC\""},{"input":"\"a\", \"aa\"","output":"\"\""}],"signature":"std::string minimumCoveringWindow(const std::string& text, const std::string& required)","default":"{}","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::string minimumCoveringWindow(const std::string& text, const std::string& required) {\n    // Find the Minimum Covering Window: implement the specified behavior.\n    return {};\n}"}},{"slug":"normalize-unix-path-cpp","title":"Normalize a Unix-Style Path","problem_statement":"Collapse repeated slashes and \".\" segments, resolve \"..\" against a previous ordinary segment when possible, and return an absolute normalized path. Relative inputs are interpreted from root.","difficulty":"Medium","topic_tags":["C++","String","Stack"],"constraints":["path.size() <= 100000","Path segments are separated by slash"],"examples":[{"input":"\"/a//b/../c/.\"","output":"\"/a/c\""},{"input":"\"../../x\"","output":"\"/x\""}],"signature":"std::string normalizePath(const std::string& path)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::string normalizePath(const std::string& path) {\n    // Normalize a Unix-Style Path: implement the specified behavior.\n    return {};\n}"}},{"slug":"case-folded-word-counts-cpp","title":"Count Case-Folded Words","problem_statement":"Split text on ASCII whitespace, lowercase ASCII letters in each token, and return distinct (word,count) pairs in lexicographic word order.","difficulty":"Medium","topic_tags":["C++","Map","String Processing"],"constraints":["text.size() <= 100000","Tokens contain ASCII letters and digits"],"examples":[{"input":"\"Oak oak PINE oak\"","output":"[(\"oak\",3),(\"pine\",1)]"},{"input":"\"red blue red\"","output":"[(\"blue\",1),(\"red\",2)]"}],"signature":"std::vector<std::pair<std::string,int>> wordCounts(const std::string& text)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<std::pair<std::string,int>> wordCounts(const std::string& text) {\n    // Count Case-Folded Words: implement the specified behavior.\n    return {};\n}"}},{"slug":"peak-concurrent-meetings-cpp","title":"Find Peak Concurrent Meetings","problem_statement":"Each meeting is a half-open interval [start,end). Return the greatest number active at once; a meeting ending at time t does not overlap one starting at t.","difficulty":"Medium","topic_tags":["C++","Sorting","Sweep Line"],"constraints":["0 <= intervals.size() <= 100000","start < end for every interval"],"examples":[{"input":"[(1,4),(2,5),(4,7)]","output":"2"},{"input":"[(0,1),(1,2)]","output":"1"}],"signature":"int peakMeetings(const std::vector<std::pair<int,int>>& intervals)","default":"0","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nint peakMeetings(const std::vector<std::pair<int,int>>& intervals) {\n    // Find Peak Concurrent Meetings: implement the specified behavior.\n    return 0;\n}"}},{"slug":"merge-k-sorted-vectors-cpp","title":"Merge K Sorted Vectors","problem_statement":"Merge all nondecreasing vectors into one nondecreasing vector, using a min-heap so the work scales with total elements times log k.","difficulty":"Hard","topic_tags":["C++","Priority Queue","Multiway Merge"],"constraints":["At most 10000 vectors","Total elements <= 200000","Every vector is sorted"],"examples":[{"input":"[ [1,4], [1,3,8], [2,9] ]","output":"[1,1,2,3,4,8,9]"},{"input":"[[],[-2,0],[]]","output":"[-2,0]"}],"signature":"std::vector<int> mergeSortedVectors(const std::vector<std::vector<int>>& lists)","default":"{}","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> mergeSortedVectors(const std::vector<std::vector<int>>& lists) {\n    // Merge K Sorted Vectors: implement the specified behavior.\n    return {};\n}"}},{"slug":"median-of-two-sorted-vectors-cpp","title":"Find the Median of Two Sorted Vectors","problem_statement":"Return the median of the combined sorted values as a double. If both vectors are empty, return 0.0. Aim for logarithmic search in the shorter vector.","difficulty":"Hard","topic_tags":["C++","Binary Search","Sorted Sequences"],"constraints":["Each input is sorted nondecreasing","Combined size <= 200000"],"examples":[{"input":"[1,3], [2]","output":"2.0"},{"input":"[1,2], [3,4]","output":"2.5"}],"signature":"double medianOfSorted(const std::vector<int>& a, const std::vector<int>& b)","default":"0.0","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\ndouble medianOfSorted(const std::vector<int>& a, const std::vector<int>& b) {\n    // Find the Median of Two Sorted Vectors: implement the specified behavior.\n    return 0.0;\n}"}},{"slug":"next-greater-circular-cpp","title":"Next Greater Value in a Circular Sequence","problem_statement":"For each position, return the first strictly greater value encountered moving forward with wraparound. Use -1 when no greater value occurs.","difficulty":"Medium","topic_tags":["C++","Stack","Monotonic Stack"],"constraints":["0 <= values.size() <= 100000","Values are signed 32-bit integers"],"examples":[{"input":"[1,2,1]","output":"[2,-1,2]"},{"input":"[5,4,3]","output":"[-1,-1,-1]"}],"signature":"std::vector<int> nextGreaterCircular(const std::vector<int>& values)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> nextGreaterCircular(const std::vector<int>& values) {\n    // Next Greater Value in a Circular Sequence: implement the specified behavior.\n    return {};\n}"}},{"slug":"evaluate-rpn-cpp","title":"Evaluate Reverse Polish Notation","problem_statement":"Evaluate integer tokens and binary operators +, -, *, /. Division truncates toward zero. The expression is valid, division by zero does not occur, and every intermediate result fits int64_t.","difficulty":"Medium","topic_tags":["C++","Stack","Expression Evaluation"],"constraints":["1 <= tokens.size() <= 100000","Tokens are valid signed integers or operators"],"examples":[{"input":"[\"4\",\"13\",\"5\",\"/\",\"+\"]","output":"6"},{"input":"[\"7\",\"2\",\"-\",\"3\",\"*\"]","output":"15"}],"signature":"long long evaluateRpn(const std::vector<std::string>& tokens)","default":"0","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nlong long evaluateRpn(const std::vector<std::string>& tokens) {\n    // Evaluate Reverse Polish Notation: implement the specified behavior.\n    return 0;\n}"}},{"slug":"group-anagrams-deterministically-cpp","title":"Group Anagrams Deterministically","problem_statement":"Group lowercase words with identical letter counts. Sort words within each group, then sort the groups by their first word.","difficulty":"Medium","topic_tags":["C++","Hashing","Canonical Keys"],"constraints":["0 <= words.size() <= 10000","Each word contains lowercase a-z only"],"examples":[{"input":"[\"eat\",\"tea\",\"tan\",\"ate\",\"nat\",\"bat\"]","output":"[[\"ate\",\"eat\",\"tea\"],[\"bat\"],[\"nat\",\"tan\"]]"},{"input":"[\"ab\",\"ba\",\"ab\"]","output":"[[\"ab\",\"ab\",\"ba\"]]"}],"signature":"std::vector<std::vector<std::string>> groupAnagrams(const std::vector<std::string>& words)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<std::vector<std::string>> groupAnagrams(const std::vector<std::string>& words) {\n    // Group Anagrams Deterministically: implement the specified behavior.\n    return {};\n}"}},{"slug":"count-graph-components-cpp","title":"Count Undirected Graph Components","problem_statement":"Vertices are numbered 0 through n-1. Return the number of connected components; duplicate edges and self-edges may appear.","difficulty":"Medium","topic_tags":["C++","Disjoint Set Union","Graph"],"constraints":["0 <= n <= 100000","All edge endpoints are valid vertices"],"examples":[{"input":"n=5, edges=[(0,1),(1,2),(3,4)]","output":"2"},{"input":"n=3, edges=[]","output":"3"}],"signature":"int connectedComponents(int n, const std::vector<std::pair<int,int>>& edges)","default":"0","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nint connectedComponents(int n, const std::vector<std::pair<int,int>>& edges) {\n    // Count Undirected Graph Components: implement the specified behavior.\n    return 0;\n}"}},{"slug":"lexicographic-topological-order-cpp","title":"Find the Lexicographically Smallest Topological Order","problem_statement":"Return the lexicographically smallest valid ordering of the directed graph's vertices. Return an empty vector if a cycle makes an ordering impossible.","difficulty":"Hard","topic_tags":["C++","Graph","Priority Queue","Topological Sort"],"constraints":["0 <= n <= 100000","Edges have valid endpoints","Duplicate edges may occur"],"examples":[{"input":"n=4, edges=[(0,2),(1,2),(2,3)]","output":"[0,1,2,3]"},{"input":"n=2, edges=[(0,1),(1,0)]","output":"[]"}],"signature":"std::vector<int> lexicographicTopologicalOrder(int n, const std::vector<std::pair<int,int>>& edges)","default":"{}","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> lexicographicTopologicalOrder(int n, const std::vector<std::pair<int,int>>& edges) {\n    // Find the Lexicographically Smallest Topological Order: implement the specified behavior.\n    return {};\n}"}},{"slug":"dijkstra-undirected-distances-cpp","title":"Compute Nonnegative Shortest-Path Distances","problem_statement":"Edges are undirected triples (u,v,weight). Return the shortest distance from source to every vertex, using -1 for unreachable vertices.","difficulty":"Medium","topic_tags":["C++","Graph","Dijkstra","Priority Queue"],"constraints":["1 <= n <= 100000","At most 200000 edges","Weights are nonnegative","Distances fit int64_t"],"examples":[{"input":"n=4, edges=[(0,1,2),(1,2,3),(0,2,9)], source=0","output":"[0,2,5,-1]"},{"input":"n=2, edges=[(0,1,0)], source=1","output":"[0,0]"}],"signature":"std::vector<long long> shortestDistances(int n, const std::vector<std::tuple<int,int,int>>& edges, int source)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<long long> shortestDistances(int n, const std::vector<std::tuple<int,int,int>>& edges, int source) {\n    // Compute Nonnegative Shortest-Path Distances: implement the specified behavior.\n    return {};\n}"}},{"slug":"count-pairs-sum-range-cpp","title":"Count Pairs Whose Sum Is in a Range","problem_statement":"Count index pairs i < j such that low <= values[i] + values[j] <= high. Return a 64-bit count; repeated values at different indices represent distinct pairs.","difficulty":"Medium","topic_tags":["C++","Sorting","Binary Search"],"constraints":["0 <= values.size() <= 100000","low <= high","Values are signed 32-bit integers"],"examples":[{"input":"[1,2,3,4], low=5, high=6","output":"3"},{"input":"[0,0,0], low=0, high=0","output":"3"}],"signature":"long long countPairsInRange(std::vector<int> values, long long low, long long high)","default":"0","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nlong long countPairsInRange(std::vector<int> values, long long low, long long high) {\n    // Count Pairs Whose Sum Is in a Range: implement the specified behavior.\n    return 0;\n}"}},{"slug":"largest-histogram-rectangle-cpp","title":"Find the Largest Histogram Rectangle","problem_statement":"Each nonnegative height is a unit-width bar. Return the greatest rectangular area contained under one or more adjacent bars.","difficulty":"Hard","topic_tags":["C++","Stack","Monotonic Stack"],"constraints":["0 <= heights.size() <= 100000","0 <= heights[i] <= 100000"],"examples":[{"input":"[2,1,5,6,2,3]","output":"10"},{"input":"[2,4]","output":"4"}],"signature":"long long largestHistogramRectangle(const std::vector<int>& heights)","default":"0","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nlong long largestHistogramRectangle(const std::vector<int>& heights) {\n    // Find the Largest Histogram Rectangle: implement the specified behavior.\n    return 0;\n}"}},{"slug":"spiral-matrix-read-cpp","title":"Read a Rectangular Matrix in Spiral Order","problem_statement":"Return matrix elements clockwise, starting at the top-left and moving inward by successive rectangular layers.","difficulty":"Medium","topic_tags":["C++","Matrix","Boundary Traversal"],"constraints":["0 <= rows,columns <= 1000","All matrix rows have equal length"],"examples":[{"input":"[ [1,2,3], [4,5,6] ]","output":"[1,2,3,6,5,4]"},{"input":"[ [1,2], [3,4], [5,6] ]","output":"[1,2,4,6,5,3]"}],"signature":"std::vector<int> spiralOrder(const std::vector<std::vector<int>>& matrix)","default":"{}","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nstd::vector<int> spiralOrder(const std::vector<std::vector<int>>& matrix) {\n    // Read a Rectangular Matrix in Spiral Order: implement the specified behavior.\n    return {};\n}"}},{"slug":"shortest-grid-path-cpp","title":"Find a Shortest Path Through an Open Grid","problem_statement":"In a rectangular grid, 0 marks an open cell and 1 a blocked cell. Return the fewest four-direction moves from the top-left to bottom-right, or -1 if unreachable. Both endpoints are open.","difficulty":"Medium","topic_tags":["C++","Grid","Breadth-First Search"],"constraints":["1 <= rows,columns <= 1000","Grid contains only 0 and 1"],"examples":[{"input":"[ [0,0,1], [1,0,0], [0,0,0] ]","output":"4"},{"input":"[ [0,1], [1,0] ]","output":"-1"}],"signature":"int shortestGridPath(const std::vector<std::vector<int>>& grid)","default":"0","points":150,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nint shortestGridPath(const std::vector<std::vector<int>>& grid) {\n    // Find a Shortest Path Through an Open Grid: implement the specified behavior.\n    return 0;\n}"}},{"slug":"shortest-subarray-at-least-target-cpp","title":"Shortest Subarray Reaching a Target","problem_statement":"Return the minimum length of a non-empty contiguous subarray with sum at least target, or -1 if none exists. Values may be negative.","difficulty":"Hard","topic_tags":["C++","Deque","Prefix Sums"],"constraints":["1 <= values.size() <= 100000","Prefix sums fit int64_t"],"examples":[{"input":"[2,-1,2], target=3","output":"3"},{"input":"[1,2], target=4","output":"-1"}],"signature":"int shortestSubarrayAtLeast(const std::vector<int>& values, long long target)","default":"0","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nint shortestSubarrayAtLeast(const std::vector<int>& values, long long target) {\n    // Shortest Subarray Reaching a Target: implement the specified behavior.\n    return 0;\n}"}},{"slug":"weighted-job-scheduling-cpp","title":"Schedule Non-Overlapping Jobs for Maximum Value","problem_statement":"Each job is (start,end,value) and occupies the half-open interval [start,end). Select a non-overlapping subset with maximum total value; return that value.","difficulty":"Hard","topic_tags":["C++","Dynamic Programming","Sorting"],"constraints":["0 <= jobs.size() <= 100000","start < end","value >= 0","Total value fits int64_t"],"examples":[{"input":"[(1,3,5),(2,5,6),(4,6,5)]","output":"10"},{"input":"[(0,2,4),(2,4,7)]","output":"11"}],"signature":"long long maximumJobValue(std::vector<std::tuple<int,int,int>> jobs)","default":"0","points":200,"starter_code_by_language":{"C++":"#include <algorithm>\n#include <cstddef>\n#include <cstdint>\n#include <deque>\n#include <forward_list>\n#include <functional>\n#include <limits>\n#include <list>\n#include <map>\n#include <numeric>\n#include <queue>\n#include <set>\n#include <stack>\n#include <string>\n#include <tuple>\n#include <unordered_map>\n#include <unordered_set>\n#include <utility>\n#include <vector>\n\nlong long maximumJobValue(std::vector<std::tuple<int,int,int>> jobs) {\n    // Schedule Non-Overlapping Jobs for Maximum Value: implement the specified behavior.\n    return 0;\n}"}}]$seed$) as seed(
  slug text, title text, problem_statement text, difficulty text,
  topic_tags text[], constraints jsonb, examples jsonb,
  points integer, starter_code_by_language jsonb
);

do $$
declare seed_count integer;
begin
  select count(*) into seed_count from coding_question_seed;
  if seed_count <> 20 then
    raise exception 'Expected exactly 20 cpp-programming seed questions, found %', seed_count;
  end if;
  if (select count(distinct slug) from coding_question_seed) <> 20
     or (select count(distinct title) from coding_question_seed) <> 20
     or (select count(distinct problem_statement) from coding_question_seed) <> 20 then
    raise exception 'Duplicate slug, title, or problem statement in cpp-programming bank';
  end if;
  if exists (
    select 1 from coding_question_seed
    where slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
       or char_length(btrim(title)) < 8
       or char_length(btrim(problem_statement)) < 100
       or problem_statement ~* '(generic task|write appropriate code|todo|your solution here)'
       or difficulty not in ('Easy','Medium','Hard')
       or cardinality(topic_tags) < 2
       or jsonb_typeof(constraints) <> 'array' or jsonb_array_length(constraints) < 2
       or jsonb_typeof(examples) <> 'array' or jsonb_array_length(examples) < 2
       or jsonb_typeof(starter_code_by_language) <> 'object'
       or starter_code_by_language <> jsonb_build_object('C++', starter_code_by_language->>'C++')
       or nullif(btrim(starter_code_by_language->>'C++'), '') is null
       or points not between 1 and 1000
  ) then
    raise exception 'Incomplete, generic, or invalid cpp-programming seed record';
  end if;
  if exists (
    select 1
    from coding_question_seed seed
    cross join lateral jsonb_array_elements(seed.examples) example(value)
    where nullif(btrim(example.value->>'input'), '') is null
       or nullif(btrim(example.value->>'output'), '') is null
  ) or exists (
    select 1 from coding_question_seed seed
    where not exists (
      select 1 from jsonb_array_elements(seed.examples) example(value)
      where example.value->>'output' not in ('[]','null','""','0')
    )
  ) then
    raise exception 'Examples must contain concrete input and nontrivial output in cpp-programming';
  end if;
  if exists (select 1 from coding_question_seed where slug = any(array['vector-unique','two-sum','stack-valid-parentheses','merge-sort','knapsack','longest-increasing-run-cpp','rotate-matrix-clockwise-cpp']::text[])) then
    raise exception 'Seed duplicates a pre-existing published cpp-programming slug';
  end if;
  if (
    select count(*)
    from public.coding_questions question
    join public.coding_test_sets collection on collection.id = question.collection_id
    where collection.slug = 'cpp-programming'
      and question.publication_status = 'published'
      and question.slug = any(array['vector-unique','two-sum','stack-valid-parentheses','merge-sort','knapsack','longest-increasing-run-cpp','rotate-matrix-clockwise-cpp']::text[])
  ) <> 7 then
    raise exception 'Expected the seven existing published cpp-programming questions';
  end if;
  if not exists (
    select 1 from public.coding_test_sets
    where slug = 'cpp-programming' and publication_status = 'published'
      and supported_languages = '["C++"]'::jsonb
  ) then
    raise exception 'Published cpp-programming collection with the required language is missing';
  end if;
end $$;

with target_collection as (
  select id from public.coding_test_sets where slug = 'cpp-programming'
), ordered_seed as (
  select collection.id as collection_id, seed.*,
         coalesce((select max(question.question_order)
                   from public.coding_questions question
                   where question.collection_id = collection.id), 0)
           + row_number() over (order by seed.slug) as question_order
  from coding_question_seed seed cross join target_collection collection
)
insert into public.coding_questions (
  collection_id, slug, title, problem_statement, difficulty, topic_tags,
  constraints, examples, starter_code_by_language, points, publication_status, question_order
)
select collection_id, slug, title, problem_statement, difficulty, topic_tags,
       constraints, examples, starter_code_by_language, points, 'published', question_order
from ordered_seed
on conflict (collection_id, slug) do nothing;

insert into public.coding_test_cases (
  question_id, case_order, test_input, expected_output, visibility
)
select question.id, example.ordinality::integer, example.value->>'input',
       example.value->>'output', 'visible'
from coding_question_seed seed
join public.coding_test_sets collection on collection.slug = 'cpp-programming'
join public.coding_questions question
  on question.collection_id = collection.id and question.slug = seed.slug
cross join lateral jsonb_array_elements(seed.examples)
  with ordinality as example(value, ordinality)
on conflict (question_id, case_order) do nothing;

commit;
